rustc_index :: newtype_index ! { # [doc = " ID of a coverage counter. Values ascend from 0."] # [doc = ""] # [doc = " Before MIR inlining, counter IDs are local to their enclosing function."] # [doc = " After MIR inlining, coverage statements may have been inlined into"] # [doc = " another function, so use the statement's source-scope to find which"] # [doc = " function/instance its IDs are meaningful for."] # [doc = ""] # [doc = " Note that LLVM handles counter IDs as `uint32_t`, so there is no need"] # [doc = " to use a larger representation on the Rust side."] # [derive (HashStable)] # [encodable] # [orderable] # [debug_format = "CounterId({})"] pub struct CounterId { } }